const http = require('http');

const baseUrl = 'http://localhost:3001/mcp/delete_file';
const projectRoot = $vars.projectRoot || '.';
const authToken = $vars.authToken || '';

const filePath = typeof $path !== 'undefined' ? $path : '';
if (!filePath) return 'Error: path is required';

const body = JSON.stringify({
  parameters: { path: filePath }
});

return new Promise((resolve, reject) => {
  const req = http.request(baseUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
      'Authorization': 'Bearer ' + authToken,
      'X-Project-Root': encodeURIComponent(projectRoot)
    }
  }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      if (res.statusCode !== 200) {
        resolve('Error: ' + res.statusCode);
      } else {
        resolve('File ' + filePath + ' deleted successfully.');
      }
    });
  });

  req.on('error', (err) => resolve('Error: ' + err.message));
  req.write(body);
  req.end();
});
